package net.muxigame.minigames.horseqa;
import com.google.gson.*;import net.minecraft.client.*;import net.muxigame.terminal.client.*;import com.cinemamod.mcef.MCEF;import org.cef.browser.*;import org.cef.handler.*;import org.cef.callback.*;
import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.*;import net.neoforged.neoforge.client.event.ClientTickEvent;
import java.nio.file.*;import org.lwjgl.glfw.GLFW;
@EventBusSubscriber(modid="local_mc_debug_qa",value=Dist.CLIENT)
public final class UmamusumeShopClientQA {
 static String lastCapture="";static int stage,cycle;static long started,opened;static volatile JsonObject dom;static boolean done;
 static Path root(){return Path.of(System.getProperty("qa.local.root"));}
 static String json(JsonObject o){return new GsonBuilder().setPrettyPrinting().create().toJson(o);}
 public static CefMessageRouter makeRouter(){return CefMessageRouter.create(new CefMessageRouter.CefMessageRouterConfig("horseQaQuery","horseQaCancel"),new CefMessageRouterHandlerAdapter(){public boolean onQuery(CefBrowser b,CefFrame f,long id,String request,boolean persistent,CefQueryCallback cb){try{var o=JsonParser.parseString(request).getAsJsonObject();if(o.has("command")&&o.get("command").getAsString().equals("resize")){Minecraft.getInstance().execute(()->{try{var mc=Minecraft.getInstance();mc.options.guiScale().set(1);GLFW.glfwSetWindowSize(mc.getWindow().getWindow(),o.get("width").getAsInt(),o.get("height").getAsInt());mc.resizeDisplay();cb.success("resized");}catch(Throwable e){cb.failure(1,e.toString());}});return true;}dom=o;Files.writeString(root().resolve("shop-dom-evidence-cycle"+cycle+".json"),json(o));cb.success("ok");}catch(Exception ex){cb.failure(1,ex.toString());}return true;}});}
 static void shot(String name)throws Exception{var mc=Minecraft.getInstance();try(var png=Screenshot.takeScreenshot(mc.getMainRenderTarget())){png.writeToFile(root().resolve(name+".png"));}var o=new JsonObject();o.addProperty("frameWidth",mc.getWindow().getWidth());o.addProperty("frameHeight",mc.getWindow().getHeight());o.addProperty("guiScale",mc.getWindow().getGuiScale());if(mc.screen instanceof TerminalScreen){for(var key:new String[]{"left","top","APP_BAR"}){var f=TerminalScreen.class.getDeclaredField(key);f.setAccessible(true);o.addProperty(key,((Number)f.get(mc.screen)).doubleValue());}}Files.writeString(root().resolve(name+"-coordinates.json"),json(o));}
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void render(ClientTickEvent.Post e){if(!Boolean.getBoolean("muxi.horse.shopClientQa")||done||!Files.exists(root().resolve("begin-shop")))return;var mc=Minecraft.getInstance();if(mc.level==null||mc.player==null)return;long now=System.currentTimeMillis();if(started==0)started=now;
 try{if(now-started>600000)throw new IllegalStateException("Bounded client QA timeout stage "+stage);
 if(stage==0){if(!MCEF.isInitialized()||!Files.exists(root().resolve("shop-server-evidence.json")))return;mc.options.guiScale().set(1);GLFW.glfwSetWindowSize(mc.getWindow().getWindow(),1920,1080);mc.resizeDisplay();mc.player.getInventory().selected=8;TerminalClient.openApp("games");opened=now;stage=1;return;}
 if(stage==1&&now-opened>7000){var browser=TerminalBrowserSession.content();if(browser==null)return;browser.executeJavaScript("window.__shopQaCycle="+cycle+";"+Files.readString(root().resolve("shop-client.js")),browser.getURL(),0);stage=2;return;}
 if(stage==2&&dom!=null){if(dom.has("error"))throw new IllegalStateException(dom.get("error").getAsString());if(dom.has("capture")&&!dom.get("capture").getAsString().equals(lastCapture)){lastCapture=dom.get("capture").getAsString();shot("shop-cycle"+cycle+"-"+lastCapture);}if(dom.has("complete")&&dom.get("complete").getAsBoolean()){shot("shop-cycle"+cycle+"-complete");var result=new JsonObject();result.addProperty("success",true);result.addProperty("actualMcefApp",true);result.addProperty("cycle",cycle);result.addProperty("productionWrites",false);result.add("dom",dom);Files.writeString(root().resolve("shop-client-result-cycle"+cycle+".json"),json(result));if(cycle<2){if(mc.screen!=null)mc.screen.onClose();TerminalBrowserSession.close();mc.setScreen(null);dom=null;cycle++;lastCapture="";opened=now;stage=3;}else{Files.writeString(root().resolve("shop-client-result.json"),json(result));done=true;}}}
 if(stage==3&&now-opened>1500){stage=0;}
 }catch(Throwable failure){done=true;try{shot("shop-failure");var result=new JsonObject();result.addProperty("success",false);result.addProperty("cycle",cycle);result.addProperty("error",failure.toString());Files.writeString(root().resolve("shop-client-result.json"),json(result));}catch(Exception ignored){} }}
}
